NOTE TITLE: [[JavaScript模块化系统解析]]

METADATA:{"uid":null,"title":"JavaScript模块化系统解析","aliases":[],"author":"ped_yc","description":null,"tags":["JS","模块化","前端工程化"],"date-created":"2024-09-16","date-modified":"2025-04-24","status":["YCDONE"],"categories":["方法论"],"type":["blog"],"created":"2025/04/24 03:59:00","modified":"2025/04/24 20:23:15"}

NOTE BLOCK CONTENT:

(cont'd) ## 二、模块化的本质

> 模块化的本质在于外部只能访问模块暴露出来的属性和方法，可以通过闭包的特性实现。

```javascript
// 原生模块模式
function moduleA() {
    var something = "something";
    var another = "another";
    function doSomething() {
        console.log(something);
    }


    function doAnother() {
        console.log(another);
    }
    return {
        doSomething: doSomething,
        doAnother: doAnother
    };
}
// 调用模块内方法
var foo = moduleA();
foo.doSomething(); // something
foo.another; // undefined

// jQuery 类型的模块
// var $ = window.jQuery()
```

在这里通过调用 moduleA() 这个函数来创建模块实例 foo，通过这个模块实例可以调用模块内暴露的变量和方法，但仍存在问题，在于 moduleA 是一个全局函数，可能会造成函数名污染。也可以使用 IIFE 的方式创建：

```javascript
// IIFE
var foo = (function(){
	var something = "something";
	var another = "another";
	function doSomething(){...}
	function doAnother(){...}
	return {
		doSomething: doSomething,
		doAnother: doAnother
	};
})()
```

这种形式避免了函数名冲突，并且实现了单例模式。

大多数模块加载器本质上就是将这种模块定义封装进一个 API，下面给出进一步实现：

```javascript
var moduleCreater = (function Manager(){
	var modules = {};
	// 通过 define 方法定义模块
	function define(id,deps,impl){
		for(let i = 0;i < deps.length;i++){
			// 在这里解包依赖数组
			deps[i] = modules[deps[i]];
		}
		modules[id] = impl.apply(imply,deps);
	}
	function get(id){
		return modules[id];
	}
	return {
		define: define,
		get: get
	}
})()
```

## 参考资料

- 《你不知道的 Javascript》（上卷）
